// Hesabat payload-undan oxunaqlı email/Telegram mətni qururuq
const p = $input.first().json.body;
const s = p.summary || {};

const actions = (p.action_items || [])
  .map(a => `• ${a.task}${a.owner ? ' — ' + a.owner : ''}${a.due ? ' (' + a.due + ')' : ''}`)
  .join('\n');

const text = [
  `📋 İclas hesabatı: ${p.topic}`,
  '',
  `${s.headline || ''}`,
  `${s.overview || ''}`,
  '',
  '✅ Əsas məqamlar:',
  ...(s.key_points || []).map(k => `• ${k}`),
  '',
  '🎯 Növbəti addımlar:',
  actions || '• (yoxdur)',
  '',
  p.card_url ? `🖼 Xülasə kartı: ${p.card_url}` : ''
].join('\n');

return [{ json: { subject: `İclas hesabatı: ${p.topic}`, text, card_url: p.card_url } }];
